#!/usr/bin/env node
import fs from 'node:fs'

import {
  breakpoints,
  breakpointWidths,
  logoBreakpointWidth,
  sidebarBreakpointWidth,
} from '../src/utils/breakpoints.ts'

const HEADER =
  '/* Generated by `yarn breakpoints:generate` from src/utils/breakpoints.ts. Do not edit. */'

const scale = breakpoints.map((key) => [key, breakpointWidths[key]])
const components = [
  ['sidebar', sidebarBreakpointWidth],
  ['logo', logoBreakpointWidth],
]

function down([key, width]) {
  return `@custom-media --lido-app-ui-breakpoint-${key}-down (width < ${width}px);`
}

function up([key, width]) {
  return `@custom-media --lido-app-ui-breakpoint-${key}-up (width >= ${width}px);`
}

export function renderCustomMedia() {
  return [
    HEADER,
    ...scale.map(down),
    ...scale.map(up),
    ...components.flatMap((entry) => [down(entry), up(entry)]),
    '',
  ].join('\n')
}

export function renderTokens() {
  return [
    HEADER,
    '',
    '/* Breakpoint widths for calc() and clamp(); media queries live in breakpoints.css */',
    ':root {',
    ...[...scale, ...components].map(
      ([key, width]) => `  --lido-app-ui-breakpoint-${key}: ${width}px;`,
    ),
    '}',
    '',
  ].join('\n')
}

if (import.meta.main) {
  fs.writeFileSync(
    new URL('../styles/breakpoints.css', import.meta.url),
    renderCustomMedia(),
  )
  fs.writeFileSync(
    new URL('../styles/breakpoint-tokens.css', import.meta.url),
    renderTokens(),
  )
}
